<script setup lang="ts">import { computed,onMounted } from 'vue';import { useRouter } from 'vue-router';import { useCalendarStore,type CalendarView as CV } from '../stores/calendar.store';import { useDeviceProfile } from '../composables/useDeviceProfile';import MonthView from '../components/calendar/MonthView.vue';import AgendaView from '../components/calendar/AgendaView.vue';import YearView from '../components/calendar/YearView.vue';import DayView from '../components/calendar/DayView.vue';import WeekView from '../components/calendar/WeekView.vue';const c=useCalendarStore(),router=useRouter(),{profile}=useDeviceProfile();const allowed=computed<CV[]>(()=>profile.value.family==='phone'?['day','month','year','agenda']:['day','week','month','year','agenda']);const component=computed(()=>c.view==='year'?YearView:c.view==='agenda'?AgendaView:c.view==='day'?DayView:c.view==='week'?WeekView:MonthView);const title=computed(()=>c.view==='year'?String(c.cursor.getFullYear()):c.cursor.toLocaleDateString('it-IT',{month:'long',year:'numeric'}));onMounted(()=>{if(profile.value.family==='phone'&&c.view==='week')c.view='month'})</script><template><div class="screen-page"><div class="screen-shell"><header class="screen-header"><button class="icon-btn" @click="router.push('/')">←</button><div><div class="eyebrow">Calendario</div><h1 class="screen-title">{{title}}</h1></div><button class="quiet-button" :disabled="c.syncing" @click="c.syncAll">{{c.syncing?'Sincronizzo…':'Sincronizza'}}</button></header><div class="calendar-toolbar"><div class="nav"><button @click="c.move(-1)">‹</button><button @click="c.goToday">Oggi</button><button @click="c.move(1)">›</button></div><div class="views"><button v-for="v in allowed" :key="v" :class="{active:c.view===v}" @click="c.view=v">{{v==='day'?'Giorno':v==='week'?'Settimana':v==='month'?'Mese':v==='year'?'Anno':'Agenda'}}</button></div></div><component :is="component" class="calendar-body"/><div v-if="!c.sources.length" class="calendar-empty glass"><b>Nessun calendario collegato</b><span>Puoi aggiungere un link ICS da Impostazioni → Calendario.</span><button class="quiet-button" @click="router.push('/settings?section=calendar')">Apri impostazioni</button></div></div></div></template><style scoped>.calendar-toolbar{display:flex;justify-content:space-between;gap:1rem;align-items:center;margin-bottom:1rem}.nav,.views{display:flex;gap:.35rem}.nav button,.views button{border:1px solid var(--glass-border);background:rgba(255,255,255,.03);color:var(--text-secondary);border-radius:999px;padding:.55rem .85rem}.views .active{background:var(--accent);color:#142019;border-color:transparent}.calendar-body{margin-top:1rem}.calendar-empty{display:grid;justify-items:center;gap:.6rem;text-align:center;margin:1.5rem auto;padding:1.5rem;border-radius:20px;max-width:620px}.calendar-empty span{color:var(--text-muted)}@media(max-width:700px){.screen-header{align-items:flex-start}.screen-title{font-size:2rem}.calendar-toolbar{align-items:stretch;flex-direction:column}.nav,.views{overflow-x:auto;padding-bottom:.2rem}.views button{flex:1;white-space:nowrap}.calendar-body{margin-top:.5rem}}</style>
